      strncpy(g_reply, text, sizeof(g_reply) - 1);
      g_reply[sizeof(g_reply) - 1] = '\0';
    }
  else
    {
      g_reply[0] = '\0';
    }

  pthread_mutex_unlock(&g_lock);
}

int vg_agent_round_init(void)
{
  int rc = 0;

  pthread_mutex_lock(&g_lock);

  if (g_client == NULL)
    {
