int vg_point_validate_name(FAR const char *name)
{
  size_t n;
  size_t i;
  unsigned char c;

  if (name == NULL)
    {
      return 0;
    }

  n = strlen(name);
  if (n < 1 || n > (VG_POINT_NAME_MAX - 1))
    {
      return 0;
    }

  for (i = 0; i < n; i++)
    {
      c = (unsigned char)name[i];
      if (c <= 0x20 || c == 0x7f || c == '=' || c == '"' || c == '\\')
        {
          return 0;
        }
    }

  return 1;
}

int vg_point_cmdline_len(int argc, char *argv[])
{
  int n = 0;
  int i;

  if (argc < 0 || argv == NULL)
    {
      return 0;
    }

  for (i = 0; i < argc; i++)
    {
      if (argv[i] == NULL)
        {
          continue;
        }

      if (n > 0)
        {
          n++;
        }

      n += (int)strlen(argv[i]);
    }

  return n;
}

