/* True when the token %s read from `field` ends at a field boundary, i.e. the
 * next character is a space or the end of the line.  `field` points at the
 * " key=" prefix, so the token starts at field + 1 + strlen(key) + 1 and the
 * character after it must be a space or NUL.  A token cut short by %s's field
 * width is caught here too: it is longer than the buffer, so the character at
 * that position is not a boundary. */

static bool token_ends_field(const char* field, const char* token)
{
    size_t token_len = strlen(token);
    const char* after;

    if (field == NULL || token == NULL || token_len == 0) {
        return false;
    }

    /* Skip the leading space and the "key=" part to reach where the token
     * must start. */

    after = strchr(field + 1, '=');
    if (after == NULL) {
        return false;
    }
    after++;

    if (strncmp(after, token, token_len) != 0) {
        return false;
    }

    after += token_len;
    return (*after == '\0' || *after == ' ' || *after == '\n'
